/** Input accepted by {@link validateCreateUser}. */
export interface CreateUserInput {
  email?: unknown;
  name?: unknown;
  age?: unknown;
}

/** Outcome of {@link validateCreateUser}. */
export interface ValidationResult {
  ok: boolean;
  errors: string[];
}

/** Response produced by {@link handleCreateUserRequest}. */
export interface CreateUserResponse {
  status: number;
  body: ValidationResult;
}

/** HTTP status codes used by the create-user endpoint. */
export const CreateUserStatus = {
  OK: 200,
  BAD_REQUEST: 400,
} as const;

/** Stable, user-facing validation messages. */
export const ValidationMessage = {
  INVALID_BODY: "request body must be a JSON object",
  INVALID_EMAIL: "email must be a valid address",
  MISSING_NAME: "name is required",
  INVALID_AGE: "age must be a non-negative integer",
} as const;

const EMAIL_SEPARATOR = "@";
const WHITESPACE = /\s/u;

/**
 * Checks that an email address has one separator with non-empty sides.
 *
 * @param value - Candidate email address.
 * @returns Whether the value has a valid email shape.
 */
function hasValidEmailShape(value: string): boolean {
  const separatorIndex = value.indexOf(EMAIL_SEPARATOR);
  const hasSingleSeparator = separatorIndex === value.lastIndexOf(EMAIL_SEPARATOR);
  const hasLocalPart = separatorIndex > 0;
  const hasDomainPart = separatorIndex < value.length - 1;

  return (
    hasSingleSeparator &&
    hasLocalPart &&
    hasDomainPart &&
    !WHITESPACE.test(value)
  );
}

/**
 * Validates a create-user request at the API boundary.
 *
 * @param input - Untrusted request data; any JSON value is accepted.
 * @returns Whether the input is valid and the list of validation errors.
 */
export function validateCreateUser(input: unknown): ValidationResult {
  const errors: string[] = [];

  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    return { ok: false, errors: [ValidationMessage.INVALID_BODY] };
  }

  const { email, name, age } = input as CreateUserInput;

  if (typeof email !== "string" || !hasValidEmailShape(email)) {
    errors.push(ValidationMessage.INVALID_EMAIL);
  }

  if (typeof name !== "string" || name.trim().length === 0) {
    errors.push(ValidationMessage.MISSING_NAME);
  }

  if (age !== undefined) {
    if (typeof age !== "number" || !Number.isInteger(age) || age < 0) {
      errors.push(ValidationMessage.INVALID_AGE);
    }
  }

  return { ok: errors.length === 0, errors };
}

/**
 * Handles a create-user request and maps the validation outcome to a status.
 *
 * @param input - Untrusted request data; any JSON value is accepted.
 * @returns HTTP status 200 for valid input, 400 for invalid input, plus the body.
 */
export function handleCreateUserRequest(input: unknown): CreateUserResponse {
  const result = validateCreateUser(input);

  return {
    status: result.ok ? CreateUserStatus.OK : CreateUserStatus.BAD_REQUEST,
    body: result,
  };
}
