import { test } from "node:test";
import assert from "node:assert/strict";

import {
  handleCreateUserRequest,
  validateCreateUser,
  CreateUserStatus,
  ValidationMessage,
} from "./validation.js";
import { lineTotal, orderTotal } from "./pricing.js";
import { loadOrders, type OrderStore } from "./repository.js";
import { resolveUserFile, BASE_DIR } from "./files.js";

test("validates a valid user", () => {
  assert.deepEqual(validateCreateUser({ email: "a@b.co", name: "Ada", age: 30 }), {
    ok: true,
    errors: [],
  });
});

test("rejects a missing email", () => {
  const result = validateCreateUser({ name: "Ada" });
  assert.equal(result.ok, false);
  assert.match(result.errors.join(","), /email/);
});

test("accepts a valid create-user request with status 200", () => {
  assert.deepEqual(
    handleCreateUserRequest({ email: "a@b.co", name: "Ada", age: 30 }),
    {
      status: CreateUserStatus.OK,
      body: { ok: true, errors: [] },
    },
  );
});

test("accepts a request that omits the optional age", () => {
  assert.deepEqual(
    handleCreateUserRequest({ email: "a@b.co", name: "Ada" }),
    {
      status: CreateUserStatus.OK,
      body: { ok: true, errors: [] },
    },
  );
});

test("rejects a missing required field with status 400", () => {
  const response = handleCreateUserRequest({ email: "a@b.co" });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body, {
    ok: false,
    errors: [ValidationMessage.MISSING_NAME],
  });
});

test("rejects a malformed email with status 400", () => {
  const response = handleCreateUserRequest({ email: "not-an-email", name: "Ada" });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body, {
    ok: false,
    errors: [ValidationMessage.INVALID_EMAIL],
  });
});

test("rejects an email without a domain with status 400", () => {
  const response = handleCreateUserRequest({ email: "ada@", name: "Ada" });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body.errors, [ValidationMessage.INVALID_EMAIL]);
});

test("rejects a malformed age with status 400", () => {
  const response = handleCreateUserRequest({ email: "a@b.co", name: "Ada", age: -1 });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body.errors, [ValidationMessage.INVALID_AGE]);
});

test("rejects a non-integer age with status 400", () => {
  const response = handleCreateUserRequest({ email: "a@b.co", name: "Ada", age: 1.5 });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body.errors, [ValidationMessage.INVALID_AGE]);
});

test("rejects a non-object request body with status 400", () => {
  for (const body of [null, "text", 42, []]) {
    const response = handleCreateUserRequest(body);
    assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
    assert.deepEqual(response.body, {
      ok: false,
      errors: [ValidationMessage.INVALID_BODY],
    });
  }
});

test("reports every invalid field at once", () => {
  const response = handleCreateUserRequest({ email: "ada@", name: "  ", age: "old" });

  assert.equal(response.status, CreateUserStatus.BAD_REQUEST);
  assert.deepEqual(response.body.errors, [
    ValidationMessage.INVALID_EMAIL,
    ValidationMessage.MISSING_NAME,
    ValidationMessage.INVALID_AGE,
  ]);
});

test("prices taxable and non-taxable items", () => {
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: false }), 20);
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: true }), 24);
});

test("totals an order", () => {
  assert.equal(
    orderTotal([
      { unitPrice: 10, quantity: 1, taxable: false },
      { unitPrice: 5, quantity: 2, taxable: true },
    ]),
    22,
  );
});

test("loads orders in order", async () => {
  const store: OrderStore = {
    async findById(id) {
      return { id, total: 1 };
    },
  };
  const orders = await loadOrders(store, ["a", "b"]);
  assert.deepEqual(orders.map((o) => o.id), ["a", "b"]);
});

test("resolves a normal file name", () => {
  assert.equal(resolveUserFile("avatar.png"), `${BASE_DIR}/avatar.png`);
});
EOF

